tool_input.content:
import { chromium } from '@playwright/test'

const BASE = 'http://127.0.0.1:8095/'
const OUT = 'artifacts'

async function blockFonts(page) {
  await page.route('**/font/**', r => r.abort())
  await page.route('**/*.woff2*', r => r.abort())
  await page.route('**/*.woff*', r => r.abort())
}

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, headless: true })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()
await blockFonts(page)
page.on('console', m => { if (m.type() === 'error') console.log('PAGE-ERR', m.text().slice(0,150)) })

// 1. 登录
await page.goto(BASE + '#/', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)
await page.fill('input[placeholder*="用户名"], input[placeholder*="身份证"], input[placeholder*="手机"]', 'zsbase')
await page.fill('input[type="password"]', 'Zs@2026Aa!')
// 勾选协议
const agree = page.locator('.login-agreement')
if (await agree.count()) await agree.first().click()
await page.click('.login-submit')
await page.waitForTimeout(2500)
console.log('AFTER-LOGIN-URL', page.url())
await page.screenshot({ path: `${OUT}/v01-after-login.png` })

// 2. 进入汛中巡检表单页
await page.goto(BASE + '#/pages/inspection/index?kind=mid', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(3500)
await page.screenshot({ path: `${OUT}/v02-inspection-mid.png`, fullPage: true })

// 检查页面内是否还有 role=alert 内联错误横幅
const alerts = await page.locator('[role="alert"]').count()
console.log('ROLE-ALERT-COUNT', alerts)
const alertTexts = await page.locator('[role="alert"]').allInnerTexts().catch(() => [])
console.log('ROLE-ALERT-TEXTS', JSON.stringify(alertTexts))

console.log('DONE')
await browser.close()

