import { chromium } from '@playwright/test'
import { writeFileSync, existsSync, readFileSync, unlinkSync } from 'fs'

const BASE = 'http://127.0.0.1:8095/'
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const ANSWER_FILE = 'artifacts/_captcha_answer.txt'
const READY_FILE = 'artifacts/_captcha_ready.txt'
if (existsSync(ANSWER_FILE)) unlinkSync(ANSWER_FILE)
if (existsSync(READY_FILE)) unlinkSync(READY_FILE)

const browser = await chromium.launch({ executablePath: exe, headless: true })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()
await page.route('**/font/**', r => r.abort())
await page.route('**/*.woff2*', r => r.abort())
page.on('console', m => { if (m.type() === 'error') console.log('PAGE-ERR', m.text().slice(0,120)) })

await page.goto(BASE + '#/', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(2500)

// 保存验证码图片
const imgs = page.locator('img')
const n = await imgs.count()
await imgs.nth(n-1).screenshot({ path: 'artifacts/captcha-live.png' })
writeFileSync(READY_FILE, 'ready')
console.log('CAPTCHA-READY saved. waiting for answer file...')

// 等待我写答案
let answer = ''
for (let i = 0; i < 120; i++) {
  if (existsSync(ANSWER_FILE)) { answer = readFileSync(ANSWER_FILE, 'utf8').trim(); if (answer) break }
  await page.waitForTimeout(500)
}
console.log('CAPTCHA-ANSWER =', answer)
if (!answer) { console.log('NO-ANSWER-ABORT'); await browser.close(); process.exit(1) }

// 填表：input[0]=用户名 input[1]=密码 input[2]=验证码
await page.locator('input').nth(0).fill('zsbase')
await page.locator('input').nth(1).fill('Zs@2026Aa!')
await page.locator('input').nth(2).fill(answer)
// 勾选协议
const agree = page.locator('.login-agreement')
if (await agree.count()) await agree.first().click()
await page.waitForTimeout(300)
await page.click('.login-submit')
await page.waitForTimeout(3000)
console.log('AFTER-LOGIN-URL', page.url())
await page.screenshot({ path: 'artifacts/v01-after-login.png' })

// 进入汛中巡检
await page.goto(BASE + '#/pages/inspection/index?kind=mid', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(4000)
await page.screenshot({ path: 'artifacts/v02-inspection-mid.png', fullPage: true })
const alerts = await page.locator('[role="alert"]').allInnerTexts().catch(() => [])
console.log('ROLE-ALERT-TEXTS', JSON.stringify(alerts))
console.log('ROLE-ALERT-COUNT', alerts.length)
await browser.close()

